 float gx,gy;long lastTap;boolean blankTap;
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==0){gx=e.getX();gy=e.getY();blankTap=screen==0&&gy>dp(80)&&gy<root.getHeight()-dp(60);}if(e.getAction()==1&&blankTap){float dy=e.getY()-gy,dx=e.getX()-gx;int g=-1;if(Math.abs(dy)>dp(100)&&Math.abs(dx)<dp(50))g=dy<0?0:1;else if(Math.abs(dy)<dp(10)&&Math.abs(dx)<dp(10)){long now=System.currentTimeMillis();if(now-lastTap<260){g=2;lastTap=0;}else lastTap=now;}if(g>=0){int action=prefs.getInt("gesture:"+g,0);if(action>0){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();if(action==1)showScreen(1);else if(action==2)showScreen(0);else settings();return true;}}}return super.dispatchTouchEvent(e);}
 org.json.JSONObject snapshot() throws Exception{org.json.JSONObject j=new org.json.JSONObject();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(!e.getKey().startsWith("design:")&&!e.getKey().startsWith("usage:")&&!e.getKey().equals("wallpaper"))j.put(e.getKey(),e.getValue());return j;}
 void applySnapshot(String raw)throws Exception{org.json.JSONObject j=new org.json.JSONObject(raw);android.content.SharedPreferences.Editor e=prefs.edit();for(String k:prefs.getAll().keySet())if(!k.startsWith("design:")&&!k.startsWith("usage:"))e.remove(k);Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();if(k.startsWith("design:")||k.startsWith("usage:")||k.equals("wallpaper"))continue;Object v=j.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof String)e.putString(k,(String)v);}e.apply();recreate();}
