 void backupResult(int req,Intent data){try{if(req==92){try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){out.write(snapshot().toString().getBytes("UTF-8"));}Toast.makeText(this,"تم التصدير",0).show();}else{try(java.io.InputStream in=getContentResolver().openInputStream(data.getData());java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>1000000)throw new Exception();}String raw=out.toString("UTF-8");new AlertDialog.Builder(this).setTitle("استبدال الإعدادات الحالية؟").setPositiveButton("استعادة",(d,k)->{try{applySnapshot(raw);}catch(Exception e){Toast.makeText(this,"ملف غير صالح",0).show();}}).setNegativeButton("إلغاء",null).show();}}}catch(Exception e){Toast.makeText(this,"تعذر معالجة الملف",0).show();}}
 void settings(){new AlertDialog.Builder(this).setTitle("BECHIR ULTRA").setItems(new String[]{"تعيين الواجهة الرئيسية","تخصيص الألوان","اختيار التطبيقات المفضلة","استعادة المظهر الأصلي","تصحيح التاريخ الهجري","حجم الأيقونات والبطاقات","التطبيقات المخفية","تصميم الساعة","تخصيص ترتيب الواجهة","خلفية الشاشة","BECHIR DESIGN STUDIO","المحرر البصري المباشر"},(d,n)->{if(n==0){try{startActivity(new Intent(android.provider.Settings.ACTION_HOME_SETTINGS));}catch(Exception e){}}else if(n==1){themeSettings();}else if(n==2)page(true);else if(n==3)applyTheme(0);else if(n==5){new AlertDialog.Builder(this).setTitle("حجم الأيقونات والبطاقات").setSingleChoiceItems(new String[]{"صغير","قياسي","كبير"},prefs.getInt("size",0)+1,(dialog,i)->{prefs.edit().putInt("size",i-1).apply();dialog.dismiss();render();}).show();}else if(n==6)hiddenSettings();else if(n==7)clockSettings();else if(n==8)layoutSettings();else if(n==9)wallpaperSettings();else if(n==10)designStudio();else if(n==11)visualStudio();else{new AlertDialog.Builder(this).setTitle("تصحيح التاريخ الهجري").setSingleChoiceItems(new String[]{"-2","-1","0","+1","+2"},prefs.getInt("hijriOffset",0)+2,(dialog,i)->{prefs.edit().putInt("hijriOffset",i-2).apply();dialog.dismiss();recreate();}).show();}}).show();}
