 void tile(LinearLayout row,App a,int weight,int height,int iconSize,int tint){LinearLayout t=column();t.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);t.setPadding(0,dp(6),0,0);t.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33ffffff),null,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(height),weight);p.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(t,p);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);t.addView(icon,new LinearLayout.LayoutParams(dp(iconSize),dp(iconSize)));TextView name=text(a.name,12,Color.WHITE);name.setMaxLines(2);name.setMinLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(dp(3),dp(4),dp(3),0);t.addView(name,new LinearLayout.LayoutParams(-1,-2));t.setOnClickListener(v->{v.animate().scaleX(.94f).scaleY(.94f).setDuration(75).withEndAction(()->{v.setScaleX(1);v.setScaleY(1);launch(a);}).start();});t.setOnLongClickListener(v->{String key="fav:"+a.key;boolean old=prefs.getBoolean(key,false);prefs.edit().putBoolean(key,!old).putBoolean("custom",true).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى المفضلة",0).show();render();return true;});}
 void render(){grid.removeAllViews();rail.removeAllViews();rowNumber=0;index.scrollTo(0,0);if(screen==0){home();return;}if(prefs.getInt("worldMode",0)>0){worldDrawer();return;}String q=search.getText().toString().toLowerCase(Locale.ROOT);String last="";LinearLayout row=null;for(App app:apps){if(prefs.getBoolean("hidden:"+app.key,false)||!app.name.toLowerCase(Locale.ROOT).contains(q))continue;String letter=app.name.isEmpty()?"#":app.name.substring(0,1).toUpperCase(Locale.ROOT);if(!letter.equals(last)){while(row!=null&&row.getChildCount()<columns())row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));TextView section=text(letter,12,headingInk());section.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);grid.addView(section,new LinearLayout.LayoutParams(-1,dp(20)));View anchor=grid.getChildAt(grid.getChildCount()-1);TextView jump=text(letter,11,headingInk());rail.addView(jump,new LinearLayout.LayoutParams(-1,dp(22)));jump.setOnClickListener(v->{for(int z=0;z<rail.getChildCount();z++)((TextView)rail.getChildAt(z)).setTextColor(headingInk());jump.setTextColor(accent());scroll.smoothScrollTo(0,anchor.getTop());});last=letter;row=null;}if(row==null||row.getChildCount()==columns()){row=new LinearLayout(this);grid.addView(row);}appCard(row,app,false);}while(row!=null&&row.getChildCount()<columns())row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
 void worldSettings(){String[] labels={"المسافة بين الأيقونة والاسم","حجم أيقونات INFINITY","المسافة بين العناصر","أسماء التطبيقات في INFINITY","عدد التطبيقات في المدار","العودة للشكل الحالي"};new AlertDialog.Builder(this).setTitle("INFINITY STUDIO").setItems(labels,(d,n)->{if(n==0)numberChoice(labels[n],"iconGap",new int[]{0,4,6,10,14,18},6);if(n==1)numberChoice(labels[n],"worldSize",new int[]{36,44,52,60,68,76},52);if(n==2)numberChoice(labels[n],"worldGap",new int[]{2,4,8,12,16},4);if(n==3){prefs.edit().putBoolean("worldNames",!prefs.getBoolean("worldNames",true)).apply();render();}if(n==4)numberChoice(labels[n],"orbitCount",new int[]{4,6,8,10},6);if(n==5){prefs.edit().putInt("worldMode",0).apply();render();}}).show();}
