 View worldTile(App app,int size,boolean tile){LinearLayout v=column();v.setGravity(Gravity.CENTER);v.setPadding(dp(2),dp(2),dp(2),dp(2));if(tile)v.setBackground(freeCard(app,dark()));ImageView icon=new ImageView(this);icon.setImageDrawable(skinIcon(app));styleIcon(icon);freeIcon(app,icon);size=Math.min(size,prefs.getInt("free:"+app.key+":size",size));v.addView(icon,new LinearLayout.LayoutParams(dp(size),dp(size)));if(prefs.getBoolean("worldNames",true)){TextView name=text(app.name,prefs.getInt("free:"+app.key+":font",prefs.getInt("visualNameSize",11)),prefs.getInt("free:"+app.key+":ink",prefs.getInt("nameColor",tile?Color.WHITE:headingInk())));name.setGravity(Gravity.CENTER);name.setMaxLines(1);name.setEllipsize(TextUtils.TruncateAt.END);v.addView(name,new LinearLayout.LayoutParams(-1,dp(22)));}v.setContentDescription(app.name);v.setOnClickListener(w->launch(app));v.setOnLongClickListener(w->{appMenu(app,false,v);return true;});return v;}
 void worldDrawer(){int mode=prefs.getInt("worldMode",0),size=prefs.getInt("worldSize",52),gap=prefs.getInt("worldGap",4);String q=search.getText().toString().toLowerCase(Locale.ROOT);ArrayList<App> visible=new ArrayList<>();for(App a:apps)if(!prefs.getBoolean("hidden:"+a.key,false)&&a.name.toLowerCase(Locale.ROOT).contains(q))visible.add(a);if(mode==3||mode==4)visible.sort((a,b)->Integer.compare(prefs.getInt("usage:"+b.key,0),prefs.getInt("usage:"+a.key,0)));if(mode==1){if(visible.isEmpty())return;int count=Math.max(4,Math.min(10,prefs.getInt("orbitCount",6)));FrameLayout orbit=new FrameLayout(this);grid.addView(orbit,new LinearLayout.LayoutParams(-1,dp(350)));orbit.setBackground(glass(dark(),30));OrbitClock clock=new OrbitClock();orbit.addView(clock,new FrameLayout.LayoutParams(dp(112),dp(112),Gravity.CENTER));clock.setOnLongClickListener(v->{clockSettings();return true;});ArrayList<View> nodes=new ArrayList<>();final int[] offset={0};final float[] angle={-90f};final int total=Math.min(count,visible.size());Runnable populate=()->{for(View node:nodes)orbit.removeView(node);nodes.clear();for(int j=0;j<total;j++){View node=worldTile(visible.get((offset[0]+j)%visible.size()),Math.min(size, count>8?36:48),false);orbit.addView(node,new FrameLayout.LayoutParams(dp(count>8?58:76),dp(76),Gravity.CENTER));nodes.add(node);}};Runnable place=()->{float radius=Math.min(orbit.getWidth(),orbit.getHeight())*.36f;for(int j=0;j<nodes.size();j++){double theta=Math.toRadians(angle[0]+360.0*j/total);nodes.get(j).setTranslationX((float)Math.cos(theta)*radius);nodes.get(j).setTranslationY((float)Math.sin(theta)*radius);}};populate.run();orbit.post(place);TextView status=text("",14,headingInk());status.setGravity(Gravity.CENTER);grid.addView(status,new LinearLayout.LayoutParams(-1,dp(32)));Runnable update=()->status.setText((offset[0]+1)+" — "+Math.min(offset[0]+total,visible.size())+" / "+visible.size());update.run();LinearLayout controls=new LinearLayout(this);grid.addView(controls);for(int j=0;j<2;j++){final int direction=j==0?-1:1;TextView button=text(j==0?"السابق  ‹":"التالي  ›",16,Color.WHITE);button.setGravity(Gravity.CENTER);button.setBackground(glass(dark(),18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(48),1);lp.setMargins(dp(4),dp(4),dp(4),dp(4));controls.addView(button,lp);button.setOnClickListener(v->{offset[0]=(offset[0]+direction*count+visible.size())%visible.size();populate.run();place.run();update.run();});}final float[] previous={0};orbit.setOnTouchListener((v,e)->{float current=(float)Math.toDegrees(Math.atan2(e.getY()-orbit.getHeight()/2f,e.getX()-orbit.getWidth()/2f));if(e.getAction()==MotionEvent.ACTION_DOWN){previous[0]=current;orbit.getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){angle[0]+=current-previous[0];previous[0]=current;place.run();return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){orbit.getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;});return;}int cols=mode==2?3:mode==4?2:mode==5?4:2;LinearLayout row=null;for(int i=0;i<visible.size();i++){if(i%cols==0){row=new LinearLayout(this);row.setGravity(Gravity.CENTER);grid.addView(row);if(mode==2&&i/cols%2==1)row.setPadding(dp(18),0,dp(18),0);}int sz=mode==3&&i<4?Math.min(76,size+14):mode==5?Math.min(44,size):size;View tile=worldTile(visible.get(i),sz,mode!=2);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(sz+34),1);lp.setMargins(dp(gap),dp(gap),dp(gap),dp(gap));row.addView(tile,lp);}if(row!=null)while(row.getChildCount()<cols)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
